// ValidateAddress validates v against the Address schema. Generated; the semantics are
// the interpreter's, without reflection.
func ValidateAddress(ctx context.Context, v *Address, reg rt.Registry) *verr.Errors {
	errs := &verr.Errors{}
	ValidateAddressInto(ctx, v, reg, errs)
	return errs
}

// ValidateAddressInto validates into a caller-owned issue list: set errs.FailFast to
// stop at the first issue, or share one list across several schemas.
func ValidateAddressInto(ctx context.Context, v *Address, reg rt.Registry, errs *verr.Errors) {
	if v == nil {
		rt.Null(errs, "$")
		return
	}
	validateAddress(ctx, v, reg, rt.Path{}, errs)
}

